from jsonb_populate_recordset(null::public.catalogs, $seed$[{"museum_id":"king-center","language":"en","museum_name":"The King Center & King Birth Home","location":"Atlanta, Georgia","text_credit":"Guide texts drafted for this project from National Park Service (Martin Luther King, Jr. National Historical Park) and King Center public pages; not official interpretive text.","categories":["Home & Neighborhood","Ebenezer Baptist Church","The King Center"]}]$seed$::jsonb)
