insert into public.works (museum_id, language, id, position, title, category, subtitle, artist, facts, object_url, image, guide)
select museum_id, language, id, position, title, category, subtitle, artist, facts, object_url, image, guide
from jsonb_populate_recordset(null::public.works, $seed$[{"museum_id":"king-center","language":"en","id":"king-01","position":0,"title":"King Birth Home","category":"Home & Neighborhood","subtitle":null,"artist":null,"facts":[{"label":"Address","value":"501 Auburn Avenue NE"},{"label":"Built","value":"1895, Queen Anne Victorian"},{"label":"Bought by the family","value":"1909, for $3,500"},{"label":"Visit","value":"Free ranger-led tours, 15 people; tickets at the visitor center"}],"object_url":"https://www.nps.gov/malu/planyourvisit/birth-home.htm","image":null,"guide":{"short":"This two-story Queen Anne house is where Martin Luther King Jr. was born on January 15, 1929, in an upstairs bedroom. It was built in 1895 for a white family, and in 1909 Reverend A. D. Williams, the pastor of Ebenezer Baptist Church, bought it for 3,500 dollars. His daughter Alberta later married a young minister, Michael King, who moved in with her family. Their children grew up here: Christine, Michael Junior, who would later be known as Martin, and Alfred Daniel. As you look at the porch and the narrow frame of the house, notice how ordinary it is. A world figure began in a family home, on a street where people knew one another.","expansion":"Rangers who lead the tour will tell you about the details of family life. In the parlor, the boys, known in the family as M. L. and A. D., took piano lessons they did not enjoy. According to the park's own tour, they once loosened the screws on the piano stool and hammered at the piano to discourage their teacher. It is a small story, but it shows a lively, mischievous child, not yet a symbol. The house is restored to look as it did when the family lived here, from 1929 into the early 1940s, so the furniture and the family photographs are chosen to match that time.","long":"Stand across the street first and take in the house as a whole. It is a two-story frame house in the Queen Anne Victorian style, built in 1895 for a white family. By 1909, when Reverend A. D. Williams bought it for 3,500 dollars, Auburn Avenue had become the center of a thriving Black community, and Williams was the pastor of Ebenezer Baptist Church just down the street. He moved in with his wife, Jennie Celeste, and their daughter Christine, who was six. She was the only one of their three children to survive infancy. On November 25, 1926, she married a minister named Michael Luther King, who moved into the family home instead of taking her to a new one. Three children were born here: Willie Christine, Michael Junior, and Alfred Daniel. Michael Junior was born on January 15, 1929, and was later known as Martin Luther King Jr., after his father changed both their names. Reverend Williams died in the house of a heart attack on March 21, 1931, and the family stayed on until the early 1940s, when they moved to a new home on Boulevard. After King's assassination in 1968, plans were made to restore the house as a museum. The tour is limited to fifteen people, free, and given on a first-come basis, so it is worth getting tickets at the visitor center early in the day. Look for the parlor piano and the family photographs as you go. The house reminds you that the movement had a childhood, and that it was grounded in a family, a church and a neighborhood."}},{"museum_id":"king-center","language":"en","id":"king-02","position":1,"title":"Fire Station No. 6","category":"Home & Neighborhood","subtitle":null,"artist":null,"facts":[{"label":"Built","value":"1894"},{"label":"In service","value":"Until 1991"},{"label":"Featured","value":"1927 American LaFrance fire engine"},{"label":"Today","value":"Preserved landmark and park visitor center"}],"object_url":"https://www.nps.gov/malu/planyourvisit/firestation_no_6.htm","image":null,"guide":{"short":"A few doors from the Birth Home stands the red-brick Fire Station No. 6. It was built in 1894 and served the neighborhood until 1991. Today it is a preserved landmark in the national park, and it is also where visitors can start. Inside, the atrium holds a beautifully restored 1927 American LaFrance fire engine. The station tells the story of how the Atlanta Fire Department was desegregated, a reminder that the struggle for equality reached ordinary workplaces, not only lunch counters and courtrooms. When the young M. L. King lived nearby, this was a working station in his neighborhood.","expansion":"Look at the fire engine in the atrium. It is a 1927 American LaFrance, restored so carefully that it looks ready to roll out of the door. It reminds you that this was a working neighborhood with a busy fire station, and that firefighting was a job that opened to Black Atlantans only after a long fight. The station is one of about thirty-five historic structures the park has documented in detail, from the Birth Home and Ebenezer Baptist Church to the building that housed the Southern Christian Leadership Conference.","long":"Fire Station No. 6 was built in 1894, a year before the Birth Home, and it served the Sweet Auburn neighborhood until 1991. That is almost a hundred years of service. As an Old Fourth Ward landmark, it is one of the places that shaped King's boyhood: it was a working part of daily life on Auburn Avenue. The National Park Service has preserved it, and it currently serves as the park's visitor center, so many people begin their visit here, getting tickets for the Birth Home tour and an orientation. The exhibit inside tells how the Atlanta Fire Department was desegregated, which connects to a larger point about the civil rights movement: it was about jobs, public services and daily dignity as much as famous marches. In the atrium you can see a restored 1927 American LaFrance fire engine, a bright piece of machinery from the years when young King was growing up not far away. The park's historic structure reports describe how each building was documented and preserved, with architectural assessments and chronologies, so that repairs keep faith with the original. Take a moment to see the station as part of the street rather than a stand-alone museum. Fire stations, churches, homes and shops stood side by side here, and that closeness is part of what made Sweet Auburn a community."}},{"museum_id":"king-center","language":"en","id":"king-03","position":2,"title":"Sweet Auburn Community","category":"Home & Neighborhood","subtitle":null,"artist":null,"facts":[{"label":"Location","value":"Auburn Avenue, Old Fourth Ward"},{"label":"Park established","value":"October 10, 1980"},{"label":"Park size","value":"About 38 acres"},{"label":"Era","value":"Jim Crow-era Black neighborhood"}],"object_url":"https://www.nps.gov/malu/the-sweet-auburn-community.htm","image":null,"guide":{"short":"Before you go inside any building, look at the street. Sweet Auburn was a flourishing Black neighborhood built during the Jim Crow era, when segregation shut African Americans out of much of public life. Here they built their own businesses, churches and social organizations. The Victorian houses around the Birth Home belonged to that community, and Coretta Scott King worked with neighbors to preserve them. When you walk Auburn Avenue, you are walking through the world that raised Martin Luther King Jr.: a place of pride, mutual support and ambition, which gave him a sense of what a community could be.","expansion":"The National Park Service calls Sweet Auburn a prime example of the segregated neighborhoods that African Americans founded in the South. Segregation was an injustice, but within it people created institutions of their own: companies, congregations, lodges and clubs. That is part of the story the park protects, and it is why the park preserves the surrounding Victorian homes and not just the single Birth Home. Notice how close everything is, the house, the fire station and the church within a few minutes' walk.","long":"The park was established on October 10, 1980, to preserve the places where Martin Luther King Jr. was born, lived, worked, worshiped and is buried. It covers about 38 acres and welcomes more than 700,000 visitors a year. But its heart is a neighborhood. Sweet Auburn grew in the Jim Crow era, when law and custom kept Black Americans out of white-owned businesses and institutions. In response, the neighborhood developed its own: countless businesses, congregations and social organizations, according to the National Park Service. A boy growing up on Auburn Avenue could see Black doctors, ministers, shopkeepers and firefighters, which is a quiet kind of education in what was possible. Even before King's death, Coretta Scott King worked closely with the community to protect the houses around his birthplace and to help residents care for their properties. The Queen Anne homes beside the Birth Home, the 1894 fire station, the church and the building that housed the Southern Christian Leadership Conference are all part of this protected landscape. So as you walk, imagine the avenue in King's childhood: crowded, proud and neighborly, and shaping the man who would later speak so powerfully about the Beloved Community."}},{"museum_id":"king-center","language":"en","id":"king-04","position":3,"title":"Historic Ebenezer Baptist Church: Heritage Sanctuary","category":"Ebenezer Baptist Church","subtitle":null,"artist":null,"facts":[{"label":"Address","value":"407 Auburn Avenue NE"},{"label":"Sanctuary completed","value":"1922"},{"label":"King's role","value":"Baptized here; co-pastor with his father, 1960 to 1968"},{"label":"Restoration","value":"Reopened April 15, 2011, to its 1960 to 1968 appearance"},{"label":"Visit note","value":"Check the NPS site for current access before visiting"}],"object_url":"https://www.nps.gov/malu/planyourvisit/ebenezer_baptist_church.htm","image":null,"guide":{"short":"This is the spiritual home of the King family. Martin Luther King Jr. was baptized here as a child, gave a trial sermon here at nineteen, and was ordained as a minister. In 1960 he became co-pastor with his father, Martin Luther King Sr., known as Daddy King, and stayed until his death in 1968. It is also where his funeral was held, on April 9, 1968. The Heritage Sanctuary has been restored to look as it did from 1960 to 1968, so when you sit in a pew, you are in the room where he preached about justice, love and nonviolence to the people who knew him best.","expansion":"The restoration was careful. Work began in 2001 with a Save America's Treasures grant. The first phase added electrical, heating, cooling and fire protection systems and repaired the roof. The Ebenezer sign above the entrance was repaired and lit for the first time since 1990. The second phase restored the sanctuary and fellowship hall to the 1960 to 1968 period, including the stained glass windows, furnishings, balcony, baptistery and pipe organ. Look for how the room feels simple but intimate, built for a congregation more than for an audience.","long":"Ebenezer Baptist Church has been a spiritual home to many people in Sweet Auburn for generations. Its sanctuary was completed in 1922, after King's maternal grandfather commissioned the church in 1914. King was baptized here as a child, and after giving a trial sermon to the congregation at nineteen, he was ordained. In 1960 he became co-pastor with his father, a position he held until his assassination on April 4, 1968. Five days later, on April 9, his funeral was held here, as a last farewell to his spiritual home, before the procession to the memorial service at Morehouse College. The National Park Service began restoring the building in 2001. The first phase, costing 1,885,000 dollars, handled systems, roof repairs and the exterior, and the hanging Ebenezer sign was relit. The second phase returned the sanctuary and fellowship hall to the period when King and his father were co-pastors. The church reopened on April 15, 2011. Today the church's active congregation worships in the newer Horizon Sanctuary across the street, while this historic building is kept as the Heritage Sanctuary. The faith King learned here is the key to his message: his demand for justice was grounded in the language of Christian love. Please note that access has changed over the years, with a temporary closure announced in late 2023, so check with the park for current opening details."}},{"museum_id":"king-center","language":"en","id":"king-05","position":4,"title":"Tomb of Dr. and Mrs. King","category":"The King Center","subtitle":null,"artist":null,"facts":[{"label":"Location","value":"Reflecting pool, The King Center, 449 Auburn Avenue NE"},{"label":"Material","value":"Georgia marble crypts"},{"label":"Coretta Scott King interred","value":"February 7, 2006"},{"label":"Earlier burial","value":"Southview Cemetery, Atlanta"}],"object_url":"https://thekingcenter.org/visit/","image":null,"guide":{"short":"On the plaza between Ebenezer Baptist Church and Freedom Hall, the crypts of Martin Luther King Jr. and Coretta Scott King rest in a long reflecting pool. They are made of Georgia marble, and appear to float on the water. Dr. King was first buried at Southview Cemetery, and later moved here. Mrs. King was laid to rest beside him in February 2006. This is a real grave, and many visitors stand quietly. The words carved on the tomb come from the spiritual that King quoted at the end of his Lincoln Memorial speech, Free at last. Take a moment of silence, and notice the water, which gives the place a calm, reflective feel.","expansion":"The setting matters. Church to the west, the King Center and Freedom Hall to the east, and the pool between them. The tomb links faith, remembrance and the continuing work of nonviolent change. It is also the resting place of a partner in the struggle. Coretta Scott King founded the King Center in 1968 and was its first president. When you look at the two crypts side by side, you are seeing a partnership of two people who shaped the movement.","long":"The tomb of Dr. and Mrs. King is the emotional center of the King Center campus. The crypts are Georgia marble, set in a long reflecting pool that lies between the historic Ebenezer Baptist Church at the west end and Freedom Hall at the east end. Dr. King was not always buried here. After his death in 1968 he was first buried at Southview Cemetery, and his remains were later moved to this site as the King Center took shape. Over the following years, the complex was built in stages, and the present structure was dedicated on January 15, 1982, which would have been his birthday. Coretta Scott King died in 2006 and was entombed beside her husband on February 7 of that year. The National Park Service notes that this is truly King's grave, and the reflecting pool was refurbished in 2017 for the fiftieth anniversary year of his assassination. According to visitor accounts, the tomb bears his famous words, Free at last, from the old spiritual he quoted at the close of the March on Washington speech in 1963. Walk slowly beside the pool. The still water, the white marble and the quiet of the visitors make this one of the most visited sites in Atlanta, and one that rewards patience."}},{"museum_id":"king-center","language":"en","id":"king-06","position":5,"title":"The Eternal Flame","category":"The King Center","subtitle":null,"artist":null,"facts":[{"label":"Location","value":"In front of the tomb, beside the Peace and Meditation Garden"},{"label":"Meaning","value":"The continuing effort to realize the Beloved Community"},{"label":"Note","value":"The flame is always lit, though hard to see in daylight"}],"object_url":"https://www.nps.gov/malu/planyourvisit/the_king_center.htm","image":null,"guide":{"short":"Beside the reflecting pool burns the Eternal Flame. According to the National Park Service, it symbolizes the continuing effort to realize Dr. King's dream of the Beloved Community: a society based on justice, goodwill and human dignity. The flame is always lit, though in bright sunlight it can be hard to see, so look closely. It is a simple symbol, and that is its power. A flame needs tending. It is a reminder that the work King began is not finished, and that each generation has to keep it alive.","expansion":"The idea of the Beloved Community runs through King's thinking. He did not see an end to segregation as the final goal, but as a step toward a society in which people truly live as neighbors. The flame stands for that long project. Visitors often notice that it sits directly in front of the tomb as you face the street, so the grave and the fire are meant to be seen together.","long":"Visitors sometimes ask whether the Eternal Flame is really lit, because on a sunny day it is almost invisible. The park answers that it is always lit. That small fact is a good lesson in itself: a flame has to be continuously cared for, and something that burns constantly can still be overlooked. According to the National Park Service, it sits beside the Coretta Scott King Peace and Meditation Garden, directly in front of the tomb as you face the street. It symbolizes the continuing effort to realize Dr. King's dream of the Beloved Community, a phrase he used for a society in which poverty, racism and violence have been overcome by love and justice. King did not treat nonviolence as a tactic only. He treated it as a way of life, a philosophy that rejects hatred even toward opponents. The flame, burning beside his tomb through every season, turns that idea into something you can see. When you stand here, think about the word continuing. The flame does not mark an ending. It marks an unfinished task, passed from the people who marched in the 1950s and 1960s to anyone who visits today."}},{"museum_id":"king-center","language":"en","id":"king-07","position":6,"title":"Coretta Scott King Peace and Meditation Garden","category":"The King Center","subtitle":null,"artist":null,"facts":[{"label":"Location","value":"Beside the Eternal Flame, The King Center"},{"label":"Feature","value":"Sculpture of microphones on a mosaic tile plinth"},{"label":"Invitation","value":"Speak into the microphones to have your own words amplified"}],"object_url":"https://www.nps.gov/malu/planyourvisit/the_king_center.htm","image":null,"guide":{"short":"Next to the Eternal Flame is the Coretta Scott King Peace and Meditation Garden. Its centerpiece is a hand-crafted sculpture of microphones on a mosaic tile plinth. Here visitors are invited to speak into the microphones and hear their own words amplified. It is a thoughtful design for a place that honors a man known for his voice. It reminds you that speaking up is not only for famous leaders. What would you say if you had the microphone? Take a moment to think about it, and about how a single voice, in the right place and time, can change things.","expansion":"The garden carries Coretta Scott King's name, and that is fitting. She founded the King Center in 1968, only two months after her husband's assassination, and served as its first president. She did more than guard his memory. She worked for peace, justice and human rights for decades, and she campaigned to make his birthday a national holiday. This garden gives her a place of her own within the complex, and it asks visitors to take part rather than to look.","long":"Most memorials ask visitors to look, listen and remember. This one asks you to speak. The Coretta Scott King Peace and Meditation Garden, beside the Eternal Flame, features a hand-crafted sculpture of microphones set on a mosaic tile plinth. Visitors can speak into it and have their own words amplified, according to the National Park Service. The design makes a quiet point about the civil rights movement. It was powered by ordinary people who found their voices: students, ministers, domestic workers, children. King's own voice is remembered for its sermons and speeches, but the movement depended on thousands of others who spoke at meetings, in churches and on the street. The garden bears the name of Coretta Scott King, who established the King Center on June 26, 1968, and became its first president. She helped turn grief into an institution devoted to nonviolent social change, and she is entombed in the reflecting pool right beside her husband. As you sit in the garden, you might think of it as a place of both reflection and responsibility. First meditate, then decide what you would say, and what you might do."}},{"museum_id":"king-center","language":"en","id":"king-08","position":7,"title":"Freedom Hall Exhibits","category":"The King Center","subtitle":null,"artist":null,"facts":[{"label":"Location","value":"The King Center, 449 Auburn Avenue NE"},{"label":"Dedicated","value":"January 15, 1982 (present structure)"},{"label":"Honors","value":"Dr. and Mrs. King, Rosa Parks, Mahatma Gandhi"},{"label":"Highlights","value":"1964 Nobel Peace Prize and King's pastoral robe, as reported by visitors"},{"label":"Hours and cost","value":"Free; about 9 am to 5 pm, check for current schedule"}],"object_url":"https://thekingcenter.org/visit/","image":null,"guide":{"short":"Freedom Hall is the exhibit space of the King Center, and admission is free. Its galleries honor Dr. and Mrs. King, and two people who inspired and shared the philosophy of nonviolence: Rosa Parks and Mahatma Gandhi. Visitors report seeing personal objects from King's life, including his 1964 Nobel Peace Prize and his pastoral robe. Freedom Hall also houses the Yolanda D. King Theatre for the Performing Arts, named for the Kings' eldest daughter. Notice the choice to put Gandhi and Parks beside King: it shows a movement with global roots and local courage.","expansion":"Think about why these three figures appear together. Gandhi's campaigns in India showed King how nonviolent resistance could challenge an empire, and King visited India in 1959 to study his legacy. Rosa Parks's refusal to give up her bus seat in Montgomery in December 1955 helped launch the bus boycott that first made King a national leader. In Freedom Hall, they appear as a chain of ideas and actions, with each person carrying the work forward.","long":"The King Center was organized in 1968, and its present building was constructed in stages beginning in the 1970s and dedicated on January 15, 1982. Freedom Hall is its public exhibit area, and entry is free. It honors Dr. King, Mrs. King, Rosa Parks and Mahatma Gandhi. The pairing is deliberate. The Kings' philosophy of nonviolence drew on Gandhi's campaigns in India, and King traveled there in 1959 as a pilgrim to learn more. Rosa Parks, whose arrest in Montgomery in December 1955 sparked the bus boycott, represents the everyday courage that gave the movement its force. Visitors describe the upstairs gallery as small but powerful, with artifacts from King's life such as his 1964 Nobel Peace Prize and his pastoral robe and sash. The Nobel Prize recognized his leadership of a movement that used nonviolence against racial injustice. The hall also contains the Yolanda D. King Theatre for the Performing Arts, a resource center, classrooms and documentary screenings. Take your time with the exhibits about Coretta Scott King. She founded the King Center and led it as its first president, building an institution to teach nonviolent social change long after the cameras had gone. Please check current opening hours and any closures with the park or the King Center before you go, since access to some buildings has changed in recent years."}}]$seed$::jsonb)
on conflict (museum_id, language, id) do update set
  position = excluded.position, title = excluded.title, category = excluded.category,
  subtitle = excluded.subtitle, artist = excluded.artist, facts = excluded.facts,
  object_url = excluded.object_url, image = excluded.image, guide = excluded.guide;
